<script>
   /*************************************************************/
   /* ModelLoader                                               */
   /* -------------------------                                 */
   /* loads PLS model from file                                 */
   /*************************************************************/

   import { FileSelector, ButtonCancel, Container, Button } from 'svelte-controls-basic';
   import { reviver } from '@mdatools-apps/shared/utils';
   import { checkPrepField } from '@mdatools-apps/shared/methods/prep.js';
   import PrepInfo from '@mdatools-apps/shared/components/PrepInfo.svelte';

   // 'model' is the object read from the file, 'ncompSelected' the number of LVs stored in it
   let { model = $bindable(), ncompSelected = $bindable() } = $props();


   // string with model file name
   let modelFile = $state('');

   // app status for handling and showing errors
   let status = $state('neutral');
   let errMsg = $state('');

   // gets model content as one large string, parse it into matrix
   function setModel(strData) {
      try{
         const m = JSON.parse(strData, reviver);

         // every step here has to hold before the next one is allowed to look inside: reaching
         // 'm.class[0]' while 'class' was missing raised a raw TypeError, and the user was shown
         // its text instead of a sentence about the file
         const isObject = v => v !== null && typeof v === 'object';
         if (!isObject(m) || !Array.isArray(m.class) || m.class[0] !== 'plsmodel') {
            throw Error('The JSON file you selected does not contain PLS model.');
         }

         // the selected number of LVs is stored next to the model and nothing ties the two
         // together, so a file edited by hand can select more than the model has. the value
         // goes straight into the session: on the test tab the results table indexes the
         // statistics with it during the first render, before the slider's clamp effect could
         // rewrite it, and the new tab has no slider and nothing else to clamp it
         if (!Number.isInteger(m.ncomp) || m.ncomp < 1) {
            throw Error('The model file is damaged: it has no valid number of LVs.');
         }
         if (!Number.isInteger(m.ncomp_selected) || m.ncomp_selected < 1) {
            throw Error('The model file is damaged: the selected number of LVs is not a whole number above zero.');
         }
         if (m.ncomp_selected > m.ncomp) {
            throw Error('The model file is damaged: it selects ' + m.ncomp_selected + ' LVs ' +
               'while the model has only ' + m.ncomp + '.');
         }

         // four more fields are read where no catch reaches: 'exclvars' by the info panel below
         // as soon as the model is set, 'varvalues' by the contributions plot for its x axis,
         // 'stat' by the scores plot for the explained variance on its axes, and 'varlabels' by
         // the predictions and residuals plots through the result, where the prediction code
         // copies it from the model. the data loader and the prediction code refuse everything
         // else a damaged file can break, with a message
         const broken = [
            ['exclvars', Array.isArray(m.exclvars)],
            ['varlabels', Array.isArray(m.varlabels)],
            ['varvalues', Array.isArray(m.varvalues)],
            ['stat', isObject(m.stat) && Array.isArray(m.stat.xexpvar) && Array.isArray(m.stat.yexpvar)],
         ].find(([, ok]) => !ok);
         if (broken) {
            throw Error("The model file is damaged: field '" + broken[0] + "' is missing or broken.");
         }

         // the preprocessing is rendered below, where no catch reaches, and applied by
         // 'app_pls_predict': the checks of a preprocessing model, none for 0 or an empty object
         try { checkPrepField(m.prep); } catch {
            throw Error('The model file is damaged: its preprocessing can not be read.');
         }

         if (Array.isArray(m.v)) {
            m.v = Float64Array.from(m.v);
         }
         m['fileName'] = modelFileName;
         model = m;
         // set here and not in an effect of the tab, which also runs when a restored session
         // mounts and overwrote the number the user had picked. the failure paths below leave
         // it as it is, as the tab effect did when the model went null
         ncompSelected = m.ncomp_selected;
         // 'neutral', which used to be 'success': nothing told the two apart
         status = 'neutral';
         errMsg = ''
      } catch (e) {
         console.error(e);
         model = null;
         status = 'error';
         // the message only: the box printed the Error object, which reads 'Error: ...'. a file
         // the parser refuses is named as such, in place of the parser's own text
         errMsg = e instanceof SyntaxError ? 'The file could not be read as JSON.'
            : e instanceof Error ? e.message : String(e);
      }
   }

   // promise for reading the JSON file
   function readFile () {
      const reader = new FileReader();
      reader.onload = () => { setModel(reader.result) };

      // without this a file which can not be read at all - moved or made unreadable between being
      // picked and the button being pressed - left the component in its neutral state, so the
      // button appeared to do nothing
      reader.onerror = () => {
         model = null;
         status = 'error';
         errMsg = 'Could not read the file: ' + (reader.error ? reader.error.message : 'unknown error');
      };

      reader.readAsText(modelFile);
   }

   function reset() {
      modelFile = '';
      model = null;
      status = 'neutral';
      errMsg = '';
   }

   // reactive expression for tracking changes of 'modelFile'
   $effect(() => {
      if (modelFile === null) {
         // if model file is empty reset status and error messages
         model = null;
         status = 'neutral';
         errMsg = '';
      } else {
         // if not just remove error messages if any
         status = 'neutral';
         errMsg = '';
      }
   });

   // file name with model without extension
   let modelFileName = $derived(modelFile ? modelFile.name.replace(/\.[^/.]+$/, "") : '');
</script>

{#if !model }

   <!-- show if data is not loaded -->
   <Container name="file-selector">
      <FileSelector bind:file={modelFile} acceptType=".json" message="Select file with model"/>
   </Container>

   {#if modelFile}
   <Container name="load-button" label="&nbsp;">
      <Button onclick={readFile} text="Load" />
   </Container>
   {/if}

{:else}

   <!-- dataset is loaded - show info and cancel button -->
   <Container name="info">
      <p class="info-text">
         <span>Model file:</span> <span title={model.fileName} class="file-name">{model.fileName}</span><br>
         <span style="color:#a0a0a0;">Model info:</span> {model.ncomp} LVs{model.center ? ', centered' : ''}{model.scale ? ', scaled' : ''}
         {#if model.ncomp_selected}
         <br><span style="color:#a0a0a0;">Optimal LVs:</span> <span style="color:#a0a0a0;">{model.ncomp_selected}</span>
         {/if}
         {#if model.prep}
         <br><span style="color:#a0a0a0;">Preprocessing: </span>
            <PrepInfo prepmodel={model.prep} />
         {/if}
         {#if model.exclvars.length > 0}
         <br><span style="color:#a0a0a0;">Excluded</span> {model.exclvars.length} <span style="color:#a0a0a0;">variables.</span>
         {/if}
      </p>
      <ButtonCancel onclick={reset} />
   </Container>

{/if}

<!-- error message -->
{#if status === 'error' || errMsg}
<Container name="error" status="error">
   <p>{errMsg}</p>
</Container>
{/if}


<style>

   .info-text {
      line-height: 1.5em;
   }
   .info-text > :global(span) {
      vertical-align:top;
      color: #a0a0a0;
   }

   .info-text > .file-name {
      display: inline-block;
      padding: 0;
      margin: 0;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      max-width: 25ch;
      color: #222;
   }

</style>