import { replacer, checkedResultOutliers } from '@mdatools-apps/shared/utils';
import { plsres_get } from '@mdatools-apps/wasm/pls.js';

/**
 * Creates CSV file with PLS result outcomes and download it as a file.
 *
 * @param {Object} res - object with PLS results.
 * @param {Object} dataset - object with dataset used to get the results.
 * @param {string} name - name of the results (e.g. 'cal').
 */
export function downloadResults(res, dataset, name, nCompSelected) {

   // an entry that names no real row is silent: it matches no whole 'i' below, so a row the
   // result has no values for is emitted and the file is written misaligned. see
   // 'checkedResultOutliers' for what is refused and why none of it is caught further down
   const outliers = checkedResultOutliers(res.outliers, dataset.values.nrows);
   let exclvars = res.exclvars;

   if (!exclvars || !Array.isArray(exclvars)) {
      exclvars = [];
   }

   // local copy for separators
   const sep = dataset.sep;
   const dec = dataset.dec;

   // every value is converted on its own. the exporter used to run one replace over the finished
   // document instead, which rewrote every dot in it: an object label 'sample.1' was exported as
   // 'sample,1', while the file name and the title were added after the replace and kept theirs,
   // so one name could be spelled two ways in the same file. only a number is converted here; a
   // string - a label, a heading or the dash of an excluded row - keeps whatever it contains
   const num2str = v => typeof v === 'number' ? String(v).replace('.', dec) : v;
   const row = values => values.map(num2str).join(sep) + sep + '\n';

   // number of rows with/without outliers. 'n' is how many rows every block read below holds,
   // so it has to be what the result actually holds. if that disagrees with the dataset the
   // file would come out silently misaligned, which is worse than not producing it at all
   const nAll = dataset.values.nrows;
   const nOut = outliers.length;
   const n = res.nrows;

   if (nAll - nOut !== n) {
      throw new Error(
         'Results do not match the dataset: ' + nAll + ' rows minus ' + nOut +
         ' excluded is not ' + n + '.'
      );
   }

   // number of responses and components
   const nResp = res.nresp;
   const nRespModel = res.nresp_model;
   const nComp = res.ncomp;

   // number of empty columns to add in addition to row name and first value
   const filler = Array(nComp).fill('');

   // vector with component names/labels and values separator
   const compNames = Array(nComp).fill(0).map((v, i) => 'LV' + (i + 1));

   // function for adding a row per object with the outcome 'block' of every component. the block
   // is read one component at a time through 'plsres_get', which is what knows how the result is
   // laid out; the offsets this file used to compute for itself drifted from it once. 'ny' is the
   // response number, used by the predictions
   function addRows(block, ny) {
      const rowlabels = dataset.objlabels;
      const cols = compNames.map((v, a) => plsres_get(res, block, a + 1, ny));

      // n - is number of rows in result objects without outliers
      // j - is an iterator along these rows
      // nAll - is a number of rows in original dataset
      // i - is an iterator along these rows
      let j = 0;
      for (let i = 0; i < nAll; i++) {

         // outlier
         if (nOut > 0 && outliers.includes(i)) {
            out += row([rowlabels[i], ...Array(nComp).fill('-')]);
            continue;
         }

         // regular
         out += row([rowlabels[i], ...cols.map(col => col[j])]);
         j = j + 1;
      }
      out += '\n';
   }

   // function for adding a titled block with component based outcomes for every row
   function addChunk(name, block) {
      out += '\n';
      out += [name + ': ',  ...filler].join(sep) + sep + '\n';
      out += ['object', ...compNames].join(sep) + sep + '\n';
      addRows(block);
   }

   // general information
   let out = '';
   out += ['Number of LVs:', nComp, ...filler].join(sep) + '\n';
   out += ['Optimal number of LVs:', nCompSelected, ...filler].join(sep) + '\n';
   out += ['Center:', res.center, ...filler].join(sep) + '\n';
   out += ['Scale:', res.scale, ...filler].join(sep) + '\n';

   if (outliers.length > 0) {
      out += ['Removed outliers:', outliers.length, ...filler].join(sep) + '\n';
   }

   if (exclvars.length > 0) {
      out += ['Excluded variables:', exclvars.length, ...filler].join(sep) + '\n';
   }

   // variances
   out += '\n';
   if (nResp > 0) {
      out += ['Variances:', '', ...filler].join(sep) + '\n';
      out += ['', ...compNames].join(sep) + sep + '\n';
      out += row(['xexpvar:', ...res.stat.xexpvar]);
      out += row(['xcumexpvar', ...res.stat.xcumexpvar]);

      out += row(['yexpvar:', ...res.stat.yexpvar]);
      out += row(['ycumexpvar:', ...res.stat.ycumexpvar]);
      out += '\n';
      out += '\n';

      for (let ny = 1; ny <= nResp; ny++) {
         out += ['Response variable:' + sep + res.varlabels[ny - 1], ...filler].join(sep) + '\n\n';

         out += ['FoMs:', ...compNames].join(sep) + sep + '\n';
         if (res.stat) {
            out += row(['RMSE', ...res.stat.rmse.getcolref(ny)]);
            out += row(['R2', ...res.stat.r2.getcolref(ny)]);
            out += row(['Slope', ...res.stat.slope.getcolref(ny)]);
            out += row(['Bias', ...res.stat.bias.getcolref(ny)]);
            out += '\n';
         }

         out += ['Predictions:', ...compNames].join(sep) + sep + '\n';
         addRows('Yp', ny);
      }
   } else {
      for (let ny = 1; ny <= nRespModel; ny++) {
         out += ['Response variable:' + sep + res.varlabels[ny - 1], ...filler].join(sep) + '\n\n';
         out += ['Predictions:', ...compNames].join(sep) + sep + '\n';
         addRows('Yp', ny);
      }

   }

   // scores and distances
   addChunk('X-scores', 'scores');
   addChunk('Score distances, h', 'hdist');
   addChunk('Orthogonal distances, q', 'qdist');

   if (res.stat) {
      addChunk('Y-scores', 'yscores');
      addChunk('Orthogonal distances, z', 'zdist');
   }

   // add header
   out = ['Data filename:', dataset.fileName, ...filler].join(dataset.sep) + '\n' + out;

   let hdr = ['PLS results (' + name + ')', 'https://mda.tools/pls/', ...filler].join(dataset.sep) + '\n\n';

   // create Blob and start download process
   const blob = new Blob([hdr + out], { type: 'text/csv' });
   const url = window.URL.createObjectURL(blob)
   const a = document.createElement('a')
   a.setAttribute('href', url)
   a.setAttribute('download', `pls-results-${name}.csv`);
   a.click()
   URL.revokeObjectURL(url)
}


/**
 * Creates JSON with model object, stringify it and download as a file.
 *
 * @param {Object} model - object with PLS model
 */
export function downloadModel(model, ncomp_selected, prepmodel) {

   const modelWithMeta = {...model, ncomp_selected, prep: prepmodel};
   const blob = new Blob([JSON.stringify(modelWithMeta, replacer)], { type: 'application/json' });
   const url = window.URL.createObjectURL(blob)
   const a = document.createElement('a')
   a.setAttribute('href', url)
   a.setAttribute('download', 'pls-model.json');
   a.click()
   URL.revokeObjectURL(url)
}
