<script>
   /*************************************************************/
   /* AppPlots component for Test tab                           */
   /* -----------------------------------                       */
   /* defines plot components, controls and parameters          */
   /*************************************************************/

   import { untrack } from 'svelte';
   import { getDefaults } from 'svelte-controls-basic';
   import { Container, Button } from 'svelte-controls-basic';

   // global plot router
   import PlotsRouter from '@mdatools-apps/shared/plots/PlotsRouter.svelte';

   // import plot components
   import PlotVariance from '@mdatools-apps/shared/plots/PlotPLSVariance.svelte';
   import PlotFoM from '@mdatools-apps/shared/plots/PlotFoM.svelte';
   import PlotPredictions from '@mdatools-apps/shared/plots/PlotPredictions.svelte';
   import PlotScores from '@mdatools-apps/shared/plots/PlotPLSScores.svelte';
   import PlotDistance from '@mdatools-apps/shared/plots/PlotPLSDistance.svelte';
   import PlotYResiduals from '@mdatools-apps/shared/plots/PlotYResiduals.svelte';

   // import plot controls components
   import { getPlotPLSVarianceControls, getPlotFoMControls, getPlotPredictionsControls,
      getPlotPLSScoresControls, getPlotPLSDistanceControls,
      getPlotYResidualsControls
   } from '@mdatools-apps/shared/plots/Controls.svelte.js';

   let {
      res,
      model,
      data,
      ncomp,
      markOutlier,
      showContributions
   } = $props();


   // the response count and the controls are taken once, from the results this component is
   // mounted with, and untrack marks that as deliberate: the tab wraps this component in an
   // '{#if}' on the results, so a new set of results arrives as a new component and never as
   // new props for this one. the controls are a plain object: the descriptors are never changed
   // after they are made, so there is nothing here for $state to track
   const nresp = untrack(() => res[Object.keys(res)[0]].nresp);

   // JSON with plot components (scope is needed for providing correct properties)
   const plots = $derived({
      // objects
      pred: {label: 'Predictions', scope: 'objects', component: PlotPredictions, buttons: buttons1},
      scores: {label: 'Scores', scope: 'objects', component: PlotScores, buttons: buttons1},
      distance: {label: 'Distances', scope: 'objects', component: PlotDistance, buttons: buttons1},
      yresiduals: {label: 'Residuals', scope: 'stats', component: PlotYResiduals},

      // statistics
      fom: {label: 'Figures of merit', scope: 'stats', component: PlotFoM},
      variance: {label: 'Variance', scope: 'stats', component: PlotVariance},
   })

   // JSON with plots controls (as Widget properties)
   const controls = untrack(() => ({
      pred: getPlotPredictionsControls(res, nresp),
      scores: getPlotPLSScoresControls(res),
      distance: getPlotPLSDistanceControls(res),
      yresiduals: getPlotYResidualsControls(res, nresp),
      fom: getPlotFoMControls(res, nresp),
      variance: getPlotPLSVarianceControls(res),
   }));

   // which controls do not apply to what the user has currently selected, and how one is
   // labelled after another. the factories set 'hidden' for what the data rules out, and Widget
   // combines the two with OR, so a rule here can never bring back a control the data has
   // excluded. a hidden control keeps its value; a plot may still read it, and while the control
   // is hidden either ignores it or is unharmed by it
   controls.scores.comp1.hiddenWhen        = (p) => p.varSet === 'XY';
   controls.scores.comp2.label             = (p) => p.varSet === 'XY' ? 'LV' : 'LV (y-axis)';
   controls.pred.showStat.hiddenWhen       = (p) => p.resID === 'both';
   controls.yresiduals.showLabels.hiddenWhen = (p) => p.plotType === 'h';

   // JSON with currently selected plots parameters
   let params = $state({
      pred: getDefaults(controls.pred),
      scores: getDefaults(controls.scores),
      distance: getDefaults(controls.distance),
      yresiduals: getDefaults(controls.yresiduals),
      fom: getDefaults(controls.fom),
      variance: getDefaults(controls.variance),
   });


   // combine main elements to be shared with all plots together
   const props = $derived({res, model, data, ncomp});

</script>

{#snippet buttons1(sel)}
   <Container label="Selected">
      <Button onclick={() => showContributions(sel)} text="plot" />
      <Button onclick={() => markOutlier(sel)} text="remove" class="destructive" />
   </Container>
{/snippet}


<PlotsRouter {plots} {controls} {props} bind:params={params} />


