<script>
   /*************************************************************/
   /* Widget for normalization                                  */
   /* -----------------------------------                       */
   /*************************************************************/

   import { Container, Select, RangeDiscrete } from 'svelte-controls-basic';
   import PrepTemplate from './PrepTemplate.svelte';

   let {
      params = $bindable([0, 0]),
      varind = $bindable(),
      settings = $bindable(),
      isOpen,
      nvars = 0,
      ...others
   } = $props();

   // prefix for the label ids the controls below are named by, unique per widget instance
   const uid = $props.id();

   // type to num maps
   const typesMap = {'snv': 0, 'area': 1, 'length': 2, 'var': 3};
   const types = Object.keys(typesMap);

   // the type shown is the parameter read back through the map and the variable index is the
   // parameter plus one; the controls write the parameters directly, so there is no copy of
   // them to keep in step
   const type = $derived(types[params[0]]);
   const varPos = $derived(params[1] + 1);

   const title = 'Normalization';

   $effect(() => {
      settings = type + (type === 'var' ? ' #' + varPos : '');
   });

   // effect to mark the variable on the plot while the panel is open
   $effect(() => {
      if (type === 'var' && isOpen) {
         varind[0] = params[1];
      } else {
         varind[0] = -1;
      }
   });
</script>


<PrepTemplate {title} {settings} {isOpen} {...others}>
   <Container label="Type" id="{uid}-type">
   <Select bind:value={() => type, v => params[0] = typesMap[v]} options={types} />
   </Container>
   {#if type === 'var'}
   <Container label="Variable index" id="{uid}-varindex">
   <RangeDiscrete bind:value={() => varPos, v => params[1] = v - 1} min={1} max={nvars} step={1} />
   </Container>
   {/if}
</PrepTemplate>

