<script>
   /*************************************************************/
   /* Root component for the application                        */
   /*************************************************************/

   import { date2str } from '@mdatools-apps/shared/utils';
   import { checkPrepField, checkPrepChain } from '@mdatools-apps/shared/methods/prep.js';

   import TrainAppContainer from './tab_train/AppContainer.svelte';
   import TestAppContainer from './tab_test/AppContainer.svelte';
   import NewAppContainer from './tab_new/AppContainer.svelte';

   import App from '@mdatools-apps/shared/components/MainApp.svelte';
   import WASM from '@mdatools-apps/wasm/pls_wasm.js';


   /* callback to check validity of JSON with session */
   function checkSession(s) {

      const keys1 = Object.keys(s);
      if (!['date', 'tab', 'train', 'test', 'new'].every(v => keys1.includes(v))) return false;

      const keys2_expected = ['model', 'calset', 'calsetp', 'calres', 'pvset', 'pvres',
         'outliers', 'exclvars', 'ncomp_selected', 'pvscalars', 'prepType', 'prepmodel', 'prepmeta', 'prepobj'];
      const keys2 = Object.keys(s.train);
      if (!keys2_expected.every(v => keys2.includes(v))) return false;

      const keys3_expected = ['model', 'testset', 'testres', 'outliers', 'ncomp_selected'];
      const keys3 = Object.keys(s.test);
      if (!keys3_expected.every(v => keys3.includes(v))) return false;

      const keys4_expected = ['model', 'newset', 'newres', 'outliers', 'ncomp_selected'];
      const keys4 = Object.keys(s.new);
      if (!keys4_expected.every(v => keys4.includes(v))) return false;

      // the keys above are required and not their values: a model or a result is 0 from
      // 'initSession', null from a loader or a reset, or an object, and every read of it is
      // guarded. the lists are read as arrays with no guard ('length' in the calculators and in
      // the loader's effect, 'includes' and 'push' on a click)
      if (![s.train.outliers, s.train.exclvars, s.train.prepobj, s.test.outliers, s.new.outliers]
            .every(Array.isArray)) return false;

      // a stored preprocessing model is rendered as soon as its tab mounts, and the chain read by
      // the creator, where no catch reaches: the checks a file passes (prep's 'checkSession' runs
      // the same); 0 and null are none
      try {
         checkPrepChain(s.train.prepobj);
         for (const p of [s.train.model?.prep, s.train.prepmodel, s.test.model?.prep,
                          s.new.model?.prep]) checkPrepField(p);
      } catch { return false; }

      return true;
   }

   /* callback to initialize new session */
   function initSession() {
      return {
         date: date2str(new Date()),
         tab: 0,
         train: {
            model : 0,
            calset: 0,
            calsetp: 0,
            calres: 0,
            pvset: 0,
            pvres: 0,
            outliers: [],
            exclvars: [],
            ncomp_selected: 1,
            pvscalars: 0,
            prepType: null,
            prepmodel: 0,
            prepmeta: 0,
            prepobj: [],
         },
         test: {
            model : 0,
            testset: 0,
            testres: 0,
            outliers: [],
            ncomp_selected: 1,
         },
         new: {
            model : 0,
            newset: 0,
            newres: 0,
            outliers: [],
            ncomp_selected: 1,
         }
      }
   }

   // app containers
   const tabs = [
      {name: 'Train', label: 'train', component: TrainAppContainer},
      {name: 'Test', label: 'test', component: TestAppContainer},
      {name: 'Predict', label: 'new', component: NewAppContainer},
   ]
</script>

<App
   appID="pls"
   appTitle="PLS"
   appShortTitle="PLS"
   appSlogan="Partial least squares regression"
   {WASM}
   {tabs}
   {initSession}
   {checkSession}
>

   {#snippet footer()}
      <p>Current release: <span>1.4.1</span>
      Feedback: <a class="paper-link" href="mailto:help@mda.tools?subject=PLS app">help@mda.tools</a>
      Tutorial: <a class="paper-link" href="Tecator.zip" download>dataset</a>
      | <a href="https://www.youtube.com/playlist?list=PLep7KM9cEyFlyTjYzT1qHeVdhXTe1zKux">video lessons</a>
      </p>
   {/snippet}

   {#snippet info()}
   <h2>Partial Least Squares regression</h2>
   <p>
      Interactive web-application for creating, testing and applying PLS models for multivariate regression
      directly in your browser. The app does not send any information to the server,
      all calculations are done locally on your device.
   </p>
   <p>
      The application uses <a href="https://doi.org/10.1016/j.aca.2023.341096">Procrustes cross-validation</a> for optimization and quality check on the training stage.
   </p>
   <p>Check out YouTube <a href="https://www.youtube.com/playlist?list=PLep7KM9cEyFlyTjYzT1qHeVdhXTe1zKux">video-lessons</a> for more details. The lessons are based on the Tecator dataset, which
   you can download from the app. These data are recorded on a Tecator Infratec Food and Feed Analyzer working in the wavelength
   range 850—1050 nm by the Near Infrared Transmission (NIT) principle. The response variable is Fat content (original
   dataset also contains moisture and protein content).
   </p>
   <h3>v. 1.4.1</h3>
   <p class="release-info">released 30/09/2026</p>
   <ul>
      <li>New higher-contrast theme for the control elements.</li>
      <li>Improved accessibility of the controls.</li>
      <li>Added possibility to save plot data as CSV file.</li>
      <li>Small bug fixes and improvements.</li>
   </ul>
   {/snippet}
</App>

